const buffer = node("buffer");
const { Buffer } = buffer;
const hex = (b) => b.toString("hex");

test("node:buffer exports", () => {
  eq(globalThis.Buffer, Buffer);
  eq(buffer.kMaxLength, buffer.constants.MAX_LENGTH);
  eq(buffer.constants.MAX_STRING_LENGTH, buffer.kStringMaxLength);
  eq(buffer.INSPECT_MAX_BYTES, 50);
  eq(buffer.Blob, globalThis.Blob);
  eq(buffer.File, globalThis.File);
  eq(buffer.atob, globalThis.atob);
  eq(buffer.btoa, globalThis.btoa);
  eq(typeof buffer.Blob, "function");
});
test("class shape", () => {
  const b = Buffer.from("ab");
  eq(b instanceof Uint8Array, true);
  eq(b instanceof Buffer, true);
  eq(Object.getPrototypeOf(Buffer.prototype), Uint8Array.prototype);
  eq(b.constructor, Buffer);
  eq(Buffer.isBuffer(b), true);
  eq(Buffer.isBuffer(new Uint8Array(1)), false);
  eq(Buffer.isBuffer(null), false);
  eq(Buffer.name, "Buffer");
});
test("alloc", () => {
  const z = Buffer.alloc(4);
  eq(hex(z), "00000000");
  eq(hex(Buffer.alloc(3, 1)), "010101");
  eq(Buffer.alloc(5, "ab").toString(), "ababa");
  eq(hex(Buffer.alloc(4, "6162", "hex")), "61626162");
  eq(hex(Buffer.alloc(2, Buffer.from([7, 8, 9]))), "0708");
  eq(Buffer.alloc(0).length, 0);
  eq(Buffer.allocUnsafe(10).length, 10);
  eq(Buffer.allocUnsafeSlow(10).length, 10);
  code(() => Buffer.alloc("5"), "ERR_INVALID_ARG_TYPE", TypeError);
  code(() => Buffer.alloc(-1), "ERR_OUT_OF_RANGE", RangeError);
  code(() => Buffer.alloc(buffer.kMaxLength + 1), "ERR_OUT_OF_RANGE", RangeError);
  code(() => Buffer.alloc(NaN), "ERR_OUT_OF_RANGE", RangeError);
});
test("allocUnsafe pool", () => {
  eq(Buffer.poolSize, 65536);
  const a = Buffer.allocUnsafe(10);
  const b = Buffer.allocUnsafe(10);
  eq(a.buffer, b.buffer);
  eq(a.byteOffset % 8, 0);
  eq(b.byteOffset % 8, 0);
  eq(b.byteOffset > a.byteOffset, true);
  eq(Buffer.allocUnsafe(40000).buffer === a.buffer, false);
  eq(Buffer.allocUnsafeSlow(10).buffer === a.buffer, false);
  eq(Buffer.alloc(10).buffer === a.buffer, false);
  const before = Buffer.allocUnsafe(0);
  eq(before.length, 0);
});
test("from", () => {
  eq(hex(Buffer.from([1, 2, 257, -1])), "010201ff");
  eq(hex(Buffer.from(Buffer.from([1, 2]))), "0102");
  eq(hex(Buffer.from(new Uint16Array([257, 2]))), "0102");
  eq(hex(Buffer.from({ length: 2, 0: 5, 1: 6 })), "0506");
  eq(hex(Buffer.from({ type: "Buffer", data: [9, 8] })), "0908");
  eq(Buffer.from(new String("xy")).toString(), "xy");
  eq(Buffer.from({ valueOf() { return "zz"; } }).toString(), "zz");
  const ab = new Uint8Array([1, 2, 3, 4]).buffer;
  const view = Buffer.from(ab, 1, 2);
  eq(hex(view), "0203");
  ab instanceof ArrayBuffer;
  new Uint8Array(ab)[1] = 9;
  eq(view[0], 9);
  eq(Buffer.from(ab).length, 4);
  code(() => Buffer.from(ab, 5), "ERR_BUFFER_OUT_OF_BOUNDS", RangeError);
  code(() => Buffer.from(ab, 1, 9), "ERR_BUFFER_OUT_OF_BOUNDS", RangeError);
  const e = code(() => Buffer.from(1), "ERR_INVALID_ARG_TYPE", TypeError);
  eq(e.message.startsWith("The first argument must be of type string or an instance of Buffer, ArrayBuffer, or Array or an Array-like Object."), true);
  code(() => Buffer.from(null), "ERR_INVALID_ARG_TYPE", TypeError);
  code(() => Buffer.from(), "ERR_INVALID_ARG_TYPE", TypeError);
});
test("legacy constructor call", () => {
  eq(Buffer(3).length, 3);
  eq(hex(Buffer(3)), "000000");
  eq(Buffer("hi").toString(), "hi");
  eq(new Buffer("hi", "utf8").toString(), "hi");
});
test("concat, compare, equals", () => {
  eq(Buffer.concat([Buffer.from("a"), Buffer.from("bc")]).toString(), "abc");
  eq(Buffer.concat([Buffer.from("abc"), Buffer.from("def")], 4).toString(), "abcd");
  eq(hex(Buffer.concat([Buffer.from("a")], 3)), "610000");
  eq(Buffer.concat([]).length, 0);
  eq(Buffer.concat([new Uint8Array([1]), Buffer.from([2])]).length, 2);
  code(() => Buffer.concat("x"), "ERR_INVALID_ARG_TYPE", TypeError);
  code(() => Buffer.concat([1]), "ERR_INVALID_ARG_TYPE", TypeError);
  eq(Buffer.compare(Buffer.from("a"), Buffer.from("b")), -1);
  eq(Buffer.compare(Buffer.from("b"), Buffer.from("a")), 1);
  eq(Buffer.compare(Buffer.from("a"), Buffer.from("a")), 0);
  eq(Buffer.compare(Buffer.from("a"), Buffer.from("ab")), -1);
  eq(Buffer.from("abc").equals(Buffer.from("abc")), true);
  eq(Buffer.from("abc").equals(new Uint8Array([97, 98, 99])), true);
  eq(Buffer.from("abc").equals(Buffer.from("abd")), false);
  code(() => Buffer.from("a").equals("a"), "ERR_INVALID_ARG_TYPE", TypeError);
  eq(Buffer.from("abcde").compare(Buffer.from("xcdy"), 1, 3, 2, 4), 0);
  eq([Buffer.from("b"), Buffer.from("a")].sort(Buffer.compare)[0].toString(), "a");
});
test("indexOf, lastIndexOf, includes", () => {
  const b = Buffer.from("hello hello");
  eq(b.indexOf("lo"), 3);
  eq(b.indexOf("lo", 4), 9);
  eq(b.indexOf("lo", -3), 9);
  eq(b.lastIndexOf("lo"), 9);
  eq(b.lastIndexOf("lo", 8), 3);
  eq(b.indexOf(0x6c), 2);
  eq(b.indexOf(Buffer.from("llo")), 2);
  eq(b.indexOf(new Uint8Array([111, 32])), 4);
  eq(b.indexOf("zz"), -1);
  eq(b.includes("hello"), true);
  eq(b.includes("nope"), false);
  eq(b.indexOf(""), 0);
  eq(b.indexOf("", 99), b.length);
  eq(b.indexOf("6c6c", "hex"), 2);
  eq(Buffer.from("a€b").indexOf("€"), 1);
  eq(Buffer.from("a€b", "utf16le").indexOf("€", 0, "utf16le"), 2);
  eq(b.indexOf(256 + 0x6c), 2);
  code(() => b.indexOf({}), "ERR_INVALID_ARG_TYPE", TypeError);
});
test("fill and write", () => {
  const b = Buffer.alloc(6);
  eq(b.fill("ab", 1, 5).toString("hex"), "006162616200");
  eq(b.fill(0).toString("hex"), "000000000000");
  eq(b.fill(0x1ff, 0, 2).toString("hex").slice(0, 4), "ffff");
  eq(Buffer.alloc(4).write("€€"), 3);
  eq(Buffer.alloc(4).write("ab", 1), 2);
  const w = Buffer.alloc(8);
  eq(w.write("abcd", 2, 2), 2);
  eq(hex(w), "0000616200000000");
  eq(w.write("ff00", 0, "hex"), 2);
  eq(w.write("hi", "latin1"), 2);
  eq(Buffer.alloc(3).write("\u{1F600}"), 0);
  eq(Buffer.alloc(3).write("ab", 2, "utf16le"), 0);
  eq(Buffer.alloc(4).write("a€", 0, "utf16le"), 4);
  code(() => w.write(1), "ERR_INVALID_ARG_TYPE", TypeError);
  code(() => w.write("a", 99), "ERR_OUT_OF_RANGE", RangeError);
  code(() => Buffer.alloc(1).fill("a", 0, 5), "ERR_OUT_OF_RANGE", RangeError);
  code(() => Buffer.alloc(1).fill("zz", "hex"), "ERR_INVALID_ARG_VALUE", TypeError);
});
test("copy", () => {
  const src = Buffer.from("abcdef");
  const dst = Buffer.alloc(4);
  eq(src.copy(dst), 4);
  eq(dst.toString(), "abcd");
  eq(src.copy(dst, 2, 4), 2);
  eq(dst.toString(), "abef");
  eq(src.copy(dst, 99), 0);
  const overlap = Buffer.from("abcdef");
  overlap.copy(overlap, 2, 0, 4);
  eq(overlap.toString(), "ababcd");
  eq(Buffer.from("xy").copy(new Uint8Array(3)), 2);
  code(() => src.copy(dst, -1), "ERR_OUT_OF_RANGE", RangeError);
  code(() => src.copy("x"), "ERR_INVALID_ARG_TYPE", TypeError);
});
test("subarray and slice share memory", () => {
  const b = Buffer.from("abcdef");
  const s = b.subarray(1, 4);
  eq(s.toString(), "bcd");
  eq(Buffer.isBuffer(s), true);
  eq(s instanceof Buffer, true);
  s[0] = 0x58;
  eq(b.toString(), "aXcdef");
  eq(b.slice(-2).toString(), "ef");
  eq(b.slice(2, 99).toString(), "cdef");
  eq(b.subarray(4, 2).length, 0);
  eq(b.slice(1, 3).buffer, b.buffer);
  eq(b.subarray(-3, -1).toString(), "de");
  eq(b.subarray().length, 6);
  eq(Buffer.isBuffer(b.map((x) => x)), true);
});
test("swap and toJSON", () => {
  eq(hex(Buffer.from([1, 2, 3, 4]).swap16()), "02010403");
  eq(hex(Buffer.from([1, 2, 3, 4]).swap32()), "04030201");
  eq(hex(Buffer.from([1, 2, 3, 4, 5, 6, 7, 8]).swap64()), "0807060504030201");
  const e = code(() => Buffer.from([1, 2, 3]).swap16(), "ERR_INVALID_BUFFER_SIZE", RangeError);
  eq(e.message, "Buffer size must be a multiple of 16-bits");
  code(() => Buffer.from([1, 2, 3, 4, 5, 6]).swap32(), "ERR_INVALID_BUFFER_SIZE", RangeError);
  code(() => Buffer.from([1, 2, 3, 4]).swap64(), "ERR_INVALID_BUFFER_SIZE", RangeError);
  same(Buffer.from([1, 2]).toJSON(), { type: "Buffer", data: [1, 2] });
  eq(JSON.stringify(Buffer.from([1, 2])), '{"type":"Buffer","data":[1,2]}');
  eq(hex(Buffer.from(JSON.parse(JSON.stringify(Buffer.from("hi"))))), "6869");
});
test("inspect", () => {
  const { inspect } = node("util");
  eq(inspect(Buffer.from("hi")), "<Buffer 68 69>");
  eq(inspect(Buffer.alloc(0)), "<Buffer >");
  eq(inspect(Buffer.alloc(52)), "<Buffer " + "00 ".repeat(49) + "00 ... 2 more bytes>");
  eq(inspect({ b: Buffer.from([1]) }), "{ b: <Buffer 01> }");
});
test("iteration and typed array behavior", () => {
  const b = Buffer.from("abc");
  eq([...b].join(), "97,98,99");
  eq(Array.from(b.entries()).length, 3);
  eq(b.length, 3);
  eq(b.byteLength, 3);
  eq(b.readUInt8(0), 97);
  eq(Object.prototype.toString.call(b), "[object Uint8Array]");
  eq(Buffer.from("abc").reverse().toString(), "cba");
});
finish();
